function applyTemplate(workspace, templateKey) {
  const template = MENU_TEMPLATES[templateKey] || MENU_TEMPLATES.cafe;
  return { ...workspace, templateKey: template.key, business: { ...workspace.business, type: template.type }, design: { ...workspace.design, ...template.design }, categories: [...template.categories], products: template.products.map(product => ({ ...product })) };
}

function cloneSeed(account=seed.account){return {...structuredClone(seed),account:{...account},onboardingCompleted:false}}
function createNewWorkspace(account){return {...cloneSeed(account),templateKey:'cafe',business:{...seed.business,name:'',slug:'',type:'Cafeteria',description:'',address:'',whatsapp:'',hours:'',published:false},onboardingCompleted:false}}
function normalizeWorkspace(workspace){return {...cloneSeed(workspace?.account||seed.account),...workspace,business:{...seed.business,...workspace?.business},design:{...seed.design,...workspace?.design},qr:{...seed.qr,...workspace?.qr},products:(workspace?.products||seed.products).map(product=>({...product}))}}
function loadAccounts(){
  try{
    const saved=JSON.parse(localStorage.getItem(ACCOUNTS_KEY)||'{}');
    const legacy=JSON.parse(localStorage.getItem(LEGACY_STORAGE_KEY)||'null');
    const demoWorkspace=normalizeWorkspace({...cloneSeed(seed.account),onboardingCompleted:true});
    const accounts={...saved};
    if(!accounts[DEMO_EMAIL])accounts[DEMO_EMAIL]={password:DEMO_PASSWORD,workspace:demoWorkspace};
    if(legacy?.account?.email&&!accounts[legacy.account.email.toLowerCase()])accounts[legacy.account.email.toLowerCase()]={password:legacy.account.password||DEMO_PASSWORD,workspace:normalizeWorkspace({...legacy,onboardingCompleted:true})};
    localStorage.setItem(ACCOUNTS_KEY,JSON.stringify(accounts));
    return accounts;
  }catch{return {[DEMO_EMAIL]:{password:DEMO_PASSWORD,workspace:normalizeWorkspace({...cloneSeed(seed.account),onboardingCompleted:true})}}}
}
function money(value) { return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value); }
function slugify(value) { return value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); }
function qrContrast(a,b){const luminance=hex=>{const channels=hex.replace('#','').match(/.{2}/g).map(value=>parseInt(value,16)/255).map(value=>value<=.03928?value/12.92:((value+.055)/1.055)**2.4);return .2126*channels[0]+.7152*channels[1]+.0722*channels[2]};const l1=luminance(a),l2=luminance(b);return (Math.max(l1,l2)+.05)/(Math.min(l1,l2)+.05)}
function optimizeImage(file,onSuccess,onError){const url=URL.createObjectURL(file);const img=new Image();img.onload=()=>{const max=900;const scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);onSuccess(canvas.toDataURL('image/webp',.82))};img.onerror=()=>{URL.revokeObjectURL(url);onError()};img.src=url}

